VALUES ('doc-09-mitre-attack-p0-16478', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-08T19:27:12.535Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PowerShower](https://attack.mitre.org/software/S0441) has sent HTTP GET and POST requests to C2 servers to send information and receive instructions.(Citation: Unit 42 Inception November 2018)", "external_references": [{"description": "Lancaster, T. (2018, November 5). Inception Attackers Target Europe with Year-old Office Vulnerability. Retrieved May 8, 2020.", "source_name": "Unit 42 Inception November 2018", "url": "https://unit42.paloaltonetworks.com/unit42-inception-attackers-target-europe-year-old-office-vulnerability/"}], "id": "relationship--a3bdd37c-f82c-4df3-94f8-63495466565c", "modified": "2026-04-29T14:23:06.148Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--53486bc7-7748-4716-8190-e4f1fde04c53", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16478', 0, 78, '09-mitre-attack', 'retrieved', 'F7D594996DC7BCD695724672524F453F78915C37D6247F9124353443A2816C08', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
