VALUES ('doc-09-mitre-attack-p0-16542', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-02-12T19:00:34.566Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkComet](https://attack.mitre.org/software/S0334) has dropped itself onto victim machines with file names such as WinDefender.Exe and winupdate.exe in an apparent attempt to masquerade as a legitimate file.(Citation: TrendMicro DarkComet Sept 2014)", "external_references": [{"description": "TrendMicro. (2014, September 03). DARKCOMET. Retrieved November 6, 2018.", "source_name": "TrendMicro DarkComet Sept 2014", "url": "https://www.trendmicro.com/vinfo/us/threat-encyclopedia/malware/DARKCOMET"}], "id": "relationship--f82724f9-846b-442e-826c-a38a74a93737", "modified": "2026-04-29T14:23:06.262Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--53ab35c2-d00e-491a-8753-41d35ae7e547", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16542', 0, 76, '09-mitre-attack', 'retrieved', '540F874B57B152161B5659A37CDC51A30F29B2FED01F5DED4AA222D46C4DDF42', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
