VALUES ('doc-09-mitre-attack-p0-16547', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-17T01:57:57.302Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NETEAGLE](https://attack.mitre.org/software/S0034) can use HTTP to download resources that contain an IP address and port number pair to connect to for C2.(Citation: FireEye APT30)", "external_references": [{"description": "FireEye Labs. (2015, April). APT30 AND THE MECHANICS OF A LONG-RUNNING CYBER ESPIONAGE OPERATION. Retrieved November 17, 2024.", "source_name": "FireEye APT30", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2015/05/20081935/rpt-apt30.pdf"}], "id": "relationship--406afc1a-4ea7-45c5-b137-7784f9ed53f3", "modified": "2026-04-29T14:23:06.013Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--53cf6cc4-65aa-445a-bcf8-c3d296f8a7a2", "spec_version": "2.1", "target_ref": "attack-pattern--7bd9c723-2f78-4309-82c5-47cad406572b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16547', 0, 77, '09-mitre-attack', 'retrieved', '637A6A17547789299F6A60880DCC7AA78C02D1C6EE14118BA3E607AAADAB5324', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
