VALUES ('doc-09-mitre-attack-p0-16601', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-01T16:45:50.764Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Before executing malicious code, [Ragnar Locker](https://attack.mitre.org/software/S0481) checks the Windows API GetLocaleInfoW and doesn''t encrypt files if it finds a former Soviet country.(Citation: FBI Ragnar Locker 2020)", "external_references": [{"description": "FBI. (2020, November 19). Indicators of Compromise Associated with Ragnar Locker Ransomware. Retrieved September 12, 2024.", "source_name": "FBI Ragnar Locker 2020", "url": "https://s3.documentcloud.org/documents/20413525/fbi-flash-indicators-of-compromise-ragnar-locker-ransomware-11192020-bc.pdf"}], "id": "relationship--93fdbd36-b577-44bd-b4db-6daadbef9cb2", "modified": "2026-04-29T14:23:06.127Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--54895630-efd2-4608-9c24-319de972a9eb", "spec_version": "2.1", "target_ref": "attack-pattern--c877e33f-1df6-40d6-b1e7-ce70f16f4979", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16601', 0, 80, '09-mitre-attack', 'retrieved', 'F2E0D85E1579B666E1E78008C2370E9556FB323886968DAD1DFE0DD15CF84109', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
