VALUES ('doc-09-mitre-attack-p0-16665', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BlackEnergy](https://attack.mitre.org/software/S0089) can gather very specific information about attached USB devices, to include device instance ID and drive geometry.(Citation: Securelist BlackEnergy Nov 2014)", "external_references": [{"description": "Baumgartner, K. and Garnaeva, M.. (2014, November 3). BE2 custom plugins, router abuse, and target profiles. Retrieved March 24, 2016.", "source_name": "Securelist BlackEnergy Nov 2014", "url": "https://securelist.com/be2-custom-plugins-router-abuse-and-target-profiles/67353/"}], "id": "relationship--7cac6ccb-d070-47da-8ebf-4034b0fddb7c", "modified": "2026-04-29T14:23:06.096Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--54cc1d4f-5c53-4f0e-9ef5-11b4998e82e4", "spec_version": "2.1", "target_ref": "attack-pattern--348f1eef-964b-4eb6-bb53-69b3dcb0c643", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16665', 0, 80, '09-mitre-attack', 'retrieved', '783C94A768167D684E1920FD56BA0F7BA40F267B27D169EE48E18B97B4ABEC52', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
