VALUES ('doc-09-mitre-attack-p0-16667', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BlackEnergy](https://attack.mitre.org/software/S0089) has used a plug-in to gather credentials stored in files on the host by various software programs, including The Bat! email client, Outlook, and Windows Credential Store.(Citation: F-Secure BlackEnergy 2014)(Citation: Securelist BlackEnergy Nov 2014)", "external_references": [{"description": "F-Secure Labs. (2014). BlackEnergy & Quedagh: The convergence of crimeware and APT attacks. Retrieved March 24, 2016.", "source_name": "F-Secure BlackEnergy 2014", "url": "https://blog-assets.f-secure.com/wp-content/uploads/2019/10/15163408/BlackEnergy_Quedagh.pdf"}, {"description": "Baumgartner, K. and Garnaeva, M.. (2014, November 3). BE2 custom plugins, router abuse, and target profiles. Retrieved March 24, 2016.", "source_name": "Securelist BlackEnergy Nov 2014", "url": "https://securelist.com/be2-custom-plugins-router-abuse-and-target-profiles/67353/"}], "id": "relationship--aec49e52-c54e-45be-a476-70aa0dc42cfb", "modified": "2026-04-29T14:23:06.163Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--54cc1d4f-5c53-4f0e-9ef5-11b4998e82e4", "spec_version": "2.1", "target_ref": "attack-pattern--837f9164-50af-4ac0-8219-379d8a74cefc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16667', 0, 117, '09-mitre-attack', 'retrieved', 'DE5DAF88AE3519BC1170CB05491E684D3CE4D618A694338DA60FD1F9A539A9C9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
