VALUES ('doc-09-mitre-attack-p0-16715', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-11T16:04:32.102Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOOSTWRITE](https://attack.mitre.org/software/S0415) has used a a 32-byte long multi-XOR key to decode data inside its payload.(Citation: FireEye FIN7 Oct 2019)\t", "external_references": [{"description": "Carr, N, et all. (2019, October 10). Mahalo FIN7: Responding to the Criminal Operators’ New Tools and Techniques. Retrieved October 11, 2019.", "source_name": "FireEye FIN7 Oct 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/10/mahalo-fin7-responding-to-new-tools-and-techniques.html"}], "id": "relationship--07bbfaa8-c62f-4abc-845c-55b28434d058", "modified": "2026-04-29T14:23:05.914Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--56d10a7f-bb42-4267-9b4c-63abb9c06010", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16715', 0, 79, '09-mitre-attack', 'retrieved', '8CEBFD63B379D016AC0D67AD4B5274E709D41BEF0A0FAD4345EB13B07EA6166E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
