VALUES ('doc-09-mitre-attack-p0-16733', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-14T22:29:26.043Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Rising Sun](https://attack.mitre.org/software/S0448) has executed commands using `cmd.exe /c “ > \\AM . tmp” 2>&1`.(Citation: McAfee Sharpshooter December 2018) ", "external_references": [{"description": "Sherstobitoff, R., Malhotra, A., et. al.. (2018, December 18). Operation Sharpshooter Campaign Targets Global Defense, Critical Infrastructure. Retrieved May 14, 2020.", "source_name": "McAfee Sharpshooter December 2018", "url": "https://www.mcafee.com/enterprise/en-us/assets/reports/rp-operation-sharpshooter.pdf"}], "id": "relationship--c1a5ba7a-659b-4ac2-90df-f3f74a3a8442", "modified": "2026-04-29T14:23:06.190Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--56e6b6c2-e573-4969-8bab-783205cebbbf", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16733', 0, 78, '09-mitre-attack', 'retrieved', '0C7779D09ABFF95DF35954A99576EEF22E3E48AEC79030834184A6DEE75593E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
