VALUES ('doc-09-mitre-attack-p0-16743', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T16:19:52.441Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NotPetya](https://attack.mitre.org/software/S0368) can use [PsExec](https://attack.mitre.org/software/S0029), which interacts with the ADMIN$ network share to execute commands on remote systems.(Citation: Talos Nyetya June 2017)(Citation: US-CERT NotPetya 2017)(Citation: PsExec Russinovich)", "external_references": [{"description": "Chiu, A. (2016, June 27). New Ransomware Variant \"Nyetya\" Compromises Systems Worldwide. Retrieved March 26, 2019.", "source_name": "Talos Nyetya June 2017", "url": "https://blog.talosintelligence.com/2017/06/worldwide-ransomware-variant.html"}, {"description": "US-CERT. (2017, July 1). Alert (TA17-181A): Petya Ransomware. Retrieved March 15, 2019.", "source_name": "US-CERT NotPetya 2017", "url": "https://www.us-cert.gov/ncas/alerts/TA17-181A"}, {"description": "Russinovich, M. (2004, June 28). PsExec. Retrieved December 17, 2015.", "source_name": "PsExec Russinovich", "url": "http://windowsitpro.com/systems-management/psexec"}], "id": "relationship--44232d0d-5a86-4662-8934-054fcc9afbb3", "modified": "2026-04-29T14:23:06.018Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5719af9d-6b16-46f9-9b28-fb019541ddbb", "spec_version": "2.1", "target_ref": "attack-pattern--4f9ca633-15c5-463c-9724-bdcd54fde541", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16743', 0, 115, '09-mitre-attack', 'retrieved', 'DEA954D72D57F7D7DD9312AC7CE424E6D4B41C68525112A8A49302C9AFEA7AE9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type":