VALUES ('doc-09-mitre-attack-p0-16748', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T16:19:52.425Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NotPetya](https://attack.mitre.org/software/S0368) contains a modified version of [Mimikatz](https://attack.mitre.org/software/S0002) to help gather credentials that are later used for lateral movement.(Citation: Talos Nyetya June 2017)(Citation: US-CERT NotPetya 2017)(Citation: NCSC Joint Report Public Tools)", "external_references": [{"description": "Chiu, A. (2016, June 27). New Ransomware Variant \"Nyetya\" Compromises Systems Worldwide. Retrieved March 26, 2019.", "source_name": "Talos Nyetya June 2017", "url": "https://blog.talosintelligence.com/2017/06/worldwide-ransomware-variant.html"}, {"description": "US-CERT. (2017, July 1). Alert (TA17-181A): Petya Ransomware. Retrieved March 15, 2019.", "source_name": "US-CERT NotPetya 2017", "url": "https://www.us-cert.gov/ncas/alerts/TA17-181A"}, {"description": "The Australian Cyber Security Centre (ACSC), the Canadian Centre for Cyber Security (CCCS), the New Zealand National Cyber Security Centre (NZ NCSC), CERT New Zealand, the UK National Cyber Security Centre (UK NCSC) and the US National Cybersecurity and Communications Integration Center (NCCIC). (2018, October 11). Joint report on publicly available hacking tools. Retrieved March 11, 2019.", "source_name": "NCSC Joint Report Public Tools", "url": "https://www.ncsc.gov.uk/report/joint-report-on-publicly-available-hacking-tools"}], "id": "relationship--7cfb528c-6c2d-4f67-b59e-c343678db839", "modified": "2026-04-29T14:23:06.096Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5719af9d-6b16-46f9-9b28-fb019541ddbb", "spec_version": "2.1", "target_ref": "attack-pattern--65f2d882-3f41-4d48-8a06-29af77ec9f90", "type": "relationship", "x_mitre_attack_sp