VALUES ('doc-09-mitre-attack-p0-16903', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XAgentOSX](https://attack.mitre.org/software/S0161) contains keylogging functionality that will monitor for active application windows and write them to the log, it can handle special characters, and it will buffer by default 50 characters before sending them out over the C2 infrastructure.(Citation: XAgentOSX 2017)", "external_references": [{"description": "Robert Falcone. (2017, February 14). XAgentOSX: Sofacy''s Xagent macOS Tool. Retrieved July 12, 2017.", "source_name": "XAgentOSX 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/02/unit42-xagentosx-sofacys-xagent-macos-tool/"}], "id": "relationship--11ed82c1-88af-4c23-860e-185505389288", "modified": "2026-04-29T14:23:05.928Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--59a97b15-8189-4d51-9404-e1ce8ea4a069", "spec_version": "2.1", "target_ref": "attack-pattern--09a60ea3-a8d1-4ae5-976e-5783248b72a4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16903', 0, 90, '09-mitre-attack', 'retrieved', '64E938FEA5B41119BBF0E3B2C1F46AE7912564529D4BDF7C484C52E90D8FB367', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
