VALUES ('doc-09-mitre-attack-p0-16912', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XAgentOSX](https://attack.mitre.org/software/S0161) contains the execFile function to execute a specified file on the system using the NSTask:launch method.(Citation: XAgentOSX 2017)", "external_references": [{"description": "Robert Falcone. (2017, February 14). XAgentOSX: Sofacy''s Xagent macOS Tool. Retrieved July 12, 2017.", "source_name": "XAgentOSX 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/02/unit42-xagentosx-sofacys-xagent-macos-tool/"}], "id": "relationship--fc4811c4-103b-48b7-9e52-20d574cfc4bf", "modified": "2026-04-29T14:23:06.267Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--59a97b15-8189-4d51-9404-e1ce8ea4a069", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16912', 0, 69, '09-mitre-attack', 'retrieved', '93361AAE2FA26C6AEC36F33150DD10B89819D138FB6226D55D9A3078DFA57A90', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
