VALUES ('doc-09-mitre-attack-p0-16914', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-21T22:15:27.604Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Green Lambert](https://attack.mitre.org/software/S0690) can use Keychain Services API functions to find and collect passwords, such as `SecKeychainFindInternetPassword` and `SecKeychainItemCopyAttributesAndData`.(Citation: Objective See Green Lambert for OSX Oct 2021)(Citation: Glitch-Cat Green Lambert ATTCK Oct 2021) ", "external_references": [{"description": "Sandvik, Runa. (2021, October 1). Made In America: Green Lambert for OS X. Retrieved March 21, 2022.", "source_name": "Objective See Green Lambert for OSX Oct 2021", "url": "https://objective-see.com/blog/blog_0x68.html"}, {"description": "Sandvik, Runa. (2021, October 18). Green Lambert and ATT&CK. Retrieved November 17, 2024.", "source_name": "Glitch-Cat Green Lambert ATTCK Oct 2021", "url": "https://web.archive.org/web/20211018145402/https://www.glitch-cat.com/blog/green-lambert-and-attack"}], "id": "relationship--46970d57-04cb-4ffb-9c7e-ff66c0811f25", "modified": "2026-04-29T14:23:06.022Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--59c8a28c-200c-4565-9af1-cbdb24870ba0", "spec_version": "2.1", "target_ref": "attack-pattern--1eaebf46-e361-4437-bc23-d5d65a3b92e3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16914', 0, 115, '09-mitre-attack', 'retrieved', 'EFDEC756DDCF1813027E732AAA61E8F8AE1A8F6AE4059B6456DCCE0C6AA20E34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
