VALUES ('doc-09-mitre-attack-p0-16948', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-16T19:00:49.595Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LockerGoga](https://attack.mitre.org/software/S0372) has been observed deleting its original launcher after execution.(Citation: CarbonBlack LockerGoga 2019)", "external_references": [{"description": "CarbonBlack Threat Analysis Unit. (2019, March 22). TAU Threat Intelligence Notification – LockerGoga Ransomware. Retrieved April 16, 2019.", "source_name": "CarbonBlack LockerGoga 2019", "url": "https://www.carbonblack.com/2019/03/22/tau-threat-intelligence-notification-lockergoga-ransomware/"}], "id": "relationship--20904798-df45-48a6-8428-9e4fb913f6ae", "modified": "2026-04-29T14:23:05.949Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5af7a825-2d9f-400d-931a-e00eb9e27f48", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16948', 0, 68, '09-mitre-attack', 'retrieved', '616B343735AE1770C7F31D673D51A60802662A6BA9B698F178030774589092E1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
