VALUES ('doc-09-mitre-attack-p0-16949', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-16T19:00:49.593Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LockerGoga](https://attack.mitre.org/software/S0372) has encrypted files, including core Windows OS files, using RSA-OAEP MGF1 and then demanded Bitcoin be paid for the decryption key.(Citation: CarbonBlack LockerGoga 2019)(Citation: Unit42 LockerGoga 2019)(Citation: Wired Lockergoga 2019)", "external_references": [{"description": "CarbonBlack Threat Analysis Unit. (2019, March 22). TAU Threat Intelligence Notification – LockerGoga Ransomware. Retrieved April 16, 2019.", "source_name": "CarbonBlack LockerGoga 2019", "url": "https://www.carbonblack.com/2019/03/22/tau-threat-intelligence-notification-lockergoga-ransomware/"}, {"description": "Harbison, M. (2019, March 26). Born This Way? Origins of LockerGoga. Retrieved April 16, 2019.", "source_name": "Unit42 LockerGoga 2019", "url": "https://unit42.paloaltonetworks.com/born-this-way-origins-of-lockergoga/"}, {"description": "Greenberg, A. (2019, March 25). A Guide to LockerGoga, the Ransomware Crippling Industrial Firms. Retrieved July 17, 2019.", "source_name": "Wired Lockergoga 2019", "url": "https://www.wired.com/story/lockergoga-ransomware-crippling-industrial-firms/"}], "id": "relationship--31daba72-fb27-45a9-9224-991032b605a8", "modified": "2026-04-29T14:23:05.982Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5af7a825-2d9f-400d-931a-e00eb9e27f48", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16949', 0, 133, '09-mitre-attack', 'retrieved', '70DF82BF710