VALUES ('doc-09-mitre-attack-p0-16952', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-17T23:32:02.493Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LockerGoga](https://attack.mitre.org/software/S0372) installation has been immediately preceded by a \"task kill\" command in order to disable anti-virus.(Citation: Wired Lockergoga 2019)", "external_references": [{"description": "Greenberg, A. (2019, March 25). A Guide to LockerGoga, the Ransomware Crippling Industrial Firms. Retrieved July 17, 2019.", "source_name": "Wired Lockergoga 2019", "url": "https://www.wired.com/story/lockergoga-ransomware-crippling-industrial-firms/"}], "id": "relationship--76a951cd-cb2c-485a-9596-b0df6302ba41", "modified": "2026-04-29T14:23:06.087Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5af7a825-2d9f-400d-931a-e00eb9e27f48", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16952', 0, 74, '09-mitre-attack', 'retrieved', '09370CB5F6CD9EF90F78F8BBA777FF37E6FE350B851AB331FE3B281BED8EB698', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
