VALUES ('doc-09-mitre-attack-p0-16956', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-03T21:00:47.603Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "On macOS, [LightSpy](https://attack.mitre.org/software/S1185) checks the existence of a process identification number (PID) file, `/Users/Shared/irc.pid`, to verify if [LightSpy](https://attack.mitre.org/software/S1185) is currently running.(Citation: Huntress LightSpy macOS 2024)", "external_references": [{"description": "Stuart Ashenbrenner, Alden Schmidt. (2024, April 25). LightSpy Malware Variant Targeting macOS. Retrieved January 3, 2025.", "source_name": "Huntress LightSpy macOS 2024", "url": "https://www.huntress.com/blog/lightspy-malware-variant-targeting-macos"}], "id": "relationship--299f512d-5afc-44b0-b4c1-9cda96306166", "modified": "2026-04-29T14:23:05.961Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b5d1e6c-e7de-4b46-ab8f-8556e8745927", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16956', 0, 79, '09-mitre-attack', 'retrieved', 'C509432F9650227638ABB1E216B8D1B7C8DACAEE5CF7468A81475CD120235F07', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
