INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-16958', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-03T21:11:17.573Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "On macOS, [LightSpy](https://attack.mitre.org/software/S1185) downloads a `.json` file from the C2 server. The `.json` file contains metadata about the plugins to be downloaded, including their URL, name, version, and MD5 hash. [LightSpy](https://attack.mitre.org/software/S1185) retrieves the plugins specified in the `.json` file, which are compiled `.dylib` files. These `.dylib` files provide task and platform specific functionality. [LightSpy](https://attack.mitre.org/software/S1185) also imports open-source libraries to manage socket connections.(Citation: Huntress LightSpy macOS 2024)", "external_references": [{"description": "Stuart Ashenbrenner, Alden Schmidt. (2024, April 25). LightSpy Malware Variant Targeting macOS. Retrieved January 3, 2025.", "source_name": "Huntress LightSpy macOS 2024", "url": "https://www.huntress.com/blog/lightspy-malware-variant-targeting-macos"}], "id": "relationship--343c91aa-d902-409b-804d-e751d6715f1a", "modified": "2026-04-29T14:23:05.989Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b5d1e6c-e7de-4b46-ab8f-8556e8745927", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16958', 0, 120, '09-mitre-attack', 'retrieved', 'D2EA302A6F3B06C9E3A7478477C4DF141F95851CFC9842FBBB2EED3F7CB3BB96', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
