INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-16959', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-24T19:58:54.953Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LightSpy](https://attack.mitre.org/software/S1185) uses Apple''s built-in AVFoundation Framework library to access the user''s camera and screen. It uses the `AVCaptureStillImage` to take a picture using the user''s camera and the `AVCaptureScreen` to take a screenshot or record the user''s screen for a specified period of time.(Citation: Huntress LightSpy macOS 2024)", "external_references": [{"description": "Stuart Ashenbrenner, Alden Schmidt. (2024, April 25). LightSpy Malware Variant Targeting macOS. Retrieved January 3, 2025.", "source_name": "Huntress LightSpy macOS 2024", "url": "https://www.huntress.com/blog/lightspy-malware-variant-targeting-macos"}], "id": "relationship--357dc150-9787-4b39-b18a-a0a38778a44f", "modified": "2026-04-29T14:23:05.991Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b5d1e6c-e7de-4b46-ab8f-8556e8745927", "spec_version": "2.1", "target_ref": "attack-pattern--0259baeb-9f63-4c69-bf10-eb038c390688", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16959', 0, 102, '09-mitre-attack', 'retrieved', '4A60057C2CF44170F813457865867A627F0D600512DA11B00C78DA54B1DD38AC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
