INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-16961', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-08T18:26:56.708Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LightSpy](https://attack.mitre.org/software/S1185)''s C2 communication is performed over WebSockets using the open source library SocketRocket with functionality such as, heartbeat, receiving commands, and updating command status.(Citation: Huntress LightSpy macOS 2024)", "external_references": [{"description": "Stuart Ashenbrenner, Alden Schmidt. (2024, April 25). LightSpy Malware Variant Targeting macOS. Retrieved January 3, 2025.", "source_name": "Huntress LightSpy macOS 2024", "url": "https://www.huntress.com/blog/lightspy-malware-variant-targeting-macos"}], "id": "relationship--5a0a5102-e52f-4766-be1b-6b9142aee8e9", "modified": "2026-04-29T14:23:06.048Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b5d1e6c-e7de-4b46-ab8f-8556e8745927", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16961', 0, 82, '09-mitre-attack', 'retrieved', 'C4C6E7558DF9BD391125E5B9AEB5C864C936C5E78057F416A29C701476E3C9EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
