VALUES ('doc-09-mitre-attack-p0-16965', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-03T21:40:14.169Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LightSpy](https://attack.mitre.org/software/S1185)''s second stage implant uses the `DeviceInformation` class to collect system information, including CPU usage, battery statistics, memory allocations, screen size, etc.(Citation: Huntress LightSpy macOS 2024)", "external_references": [{"description": "Stuart Ashenbrenner, Alden Schmidt. (2024, April 25). LightSpy Malware Variant Targeting macOS. Retrieved January 3, 2025.", "source_name": "Huntress LightSpy macOS 2024", "url": "https://www.huntress.com/blog/lightspy-malware-variant-targeting-macos"}], "id": "relationship--6d965ba4-b5f3-40ce-9153-b328e4b54429", "modified": "2026-04-29T14:23:06.074Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5b5d1e6c-e7de-4b46-ab8f-8556e8745927", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16965', 0, 80, '09-mitre-attack', 'retrieved', 'DA7B2743D887DA3FE72911A781E9BABD28EAADA72B3C990005E9378B29FC81EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
