VALUES ('doc-09-mitre-attack-p0-17010', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-25T21:45:21.080Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GoldMax](https://attack.mitre.org/software/S0588) has used filenames that matched the system name, and appeared as a scheduled task impersonating systems management software within the corresponding ProgramData subfolder.(Citation: MSTIC NOBELIUM Mar 2021)(Citation: CrowdStrike StellarParticle January 2022)", "external_references": [{"description": "Nafisi, R., Lelli, A. (2021, March 4). GoldMax, GoldFinder, and Sibot: Analyzing NOBELIUM’s layered persistence. Retrieved March 8, 2021.", "source_name": "MSTIC NOBELIUM Mar 2021", "url": "https://www.microsoft.com/security/blog/2021/03/04/goldmax-goldfinder-sibot-analyzing-nobelium-malware/"}, {"description": "CrowdStrike. (2022, January 27). Early Bird Catches the Wormhole: Observations from the StellarParticle Campaign. Retrieved February 7, 2022.", "source_name": "CrowdStrike StellarParticle January 2022", "url": "https://www.crowdstrike.com/blog/observations-from-the-stellarparticle-campaign/"}], "id": "relationship--bf672181-ef16-4d3a-a587-9ac82ac87b8a", "modified": "2026-04-29T14:23:06.187Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5c747acd-47f0-4c5a-b9e5-213541fc01e0", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17010', 0, 115, '09-mitre-attack', 'retrieved', '8662CA4F559A5DFB042E4636AEB99B1E405CAA328A817A0C71FBFD4BEE942F8A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_