VALUES ('doc-09-mitre-attack-p0-17011', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-12T16:55:09.342Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GoldMax](https://attack.mitre.org/software/S0588) has set an execution trigger date and time, stored as an ASCII Unix/Epoch time value.(Citation: MSTIC NOBELIUM Mar 2021)", "external_references": [{"description": "Nafisi, R., Lelli, A. (2021, March 4). GoldMax, GoldFinder, and Sibot: Analyzing NOBELIUM’s layered persistence. Retrieved March 8, 2021.", "source_name": "MSTIC NOBELIUM Mar 2021", "url": "https://www.microsoft.com/security/blog/2021/03/04/goldmax-goldfinder-sibot-analyzing-nobelium-malware/"}], "id": "relationship--cbc18998-67f4-493a-b0d3-4aa50da3c407", "modified": "2026-04-29T14:23:06.204Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5c747acd-47f0-4c5a-b9e5-213541fc01e0", "spec_version": "2.1", "target_ref": "attack-pattern--4bed873f-0b7d-41d4-b93a-b6905d1f90b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17011', 0, 77, '09-mitre-attack', 'retrieved', '494CE8CA1FC146FAC0E933ED3E6C4B5F160142E965B40B222EAC32D1B81FA11F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
