VALUES ('doc-09-mitre-attack-p0-17028', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-27T14:14:16.819Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cheerscrypt has leveraged `esxcli` in order to terminate running virtual machines.(Citation: Trend Micro Cheerscrypt May 2022)\n", "external_references": [{"description": "Dela Cruz, A. et al. (2022, May 25). New Linux-Based Ransomware Cheerscrypt Targeting ESXi Devices Linked to Leaked Babuk Source Code. Retrieved December 19, 2023.", "source_name": "Trend Micro Cheerscrypt May 2022", "url": "https://www.trendmicro.com/en_se/research/22/e/new-linux-based-ransomware-cheerscrypt-targets-exsi-devices.html"}], "id": "relationship--31e310c0-8af4-443e-aa52-6f9cdcece312", "modified": "2026-04-29T14:23:05.982Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5d3fa1db-5041-4560-b87b-8f61cc225c52", "spec_version": "2.1", "target_ref": "attack-pattern--d2d642da-61ff-4211-b4df-7923c9ca220c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17028', 0, 80, '09-mitre-attack', 'retrieved', '38EBD844EF7F301796EF8FC98068DE72D65F6035DEDF8607BC714227F30E6145', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
