VALUES ('doc-09-mitre-attack-p0-17029', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-12-21T21:03:36.958Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cheerscrypt](https://attack.mitre.org/software/S1096) can encrypt data on victim machines using a Sosemanuk stream cipher with an Elliptic-curve Diffie–Hellman (ECDH) generated key.(Citation: Trend Micro Cheerscrypt May 2022)(Citation: Sygnia Emperor Dragonfly October 2022)\n", "external_references": [{"description": "Biderman, O. et al. (2022, October 3). REVEALING EMPEROR DRAGONFLY: NIGHT SKY AND CHEERSCRYPT - A SINGLE RANSOMWARE GROUP. Retrieved December 6, 2023.", "source_name": "Sygnia Emperor Dragonfly October 2022", "url": "https://blog.sygnia.co/revealing-emperor-dragonfly-a-chinese-ransomware-group"}, {"description": "Dela Cruz, A. et al. (2022, May 25). New Linux-Based Ransomware Cheerscrypt Targeting ESXi Devices Linked to Leaked Babuk Source Code. Retrieved December 19, 2023.", "source_name": "Trend Micro Cheerscrypt May 2022", "url": "https://www.trendmicro.com/en_se/research/22/e/new-linux-based-ransomware-cheerscrypt-targets-exsi-devices.html"}], "id": "relationship--50fc9c04-4251-43f3-8c88-3fc58a3b4b5b", "modified": "2026-04-29T14:23:06.036Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5d3fa1db-5041-4560-b87b-8f61cc225c52", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17029', 0, 125, '09-mitre-attack', 'retrieved', '830CBF957668F09010EAAAC59E1B4146E128C74712776DB448B85F5C2A0429FD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type"