VALUES ('doc-09-mitre-attack-p0-17110', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-06T19:13:41.187Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Line Runner](https://attack.mitre.org/software/S1188) removes its initial ZIP delivery archive after processing the enclosed LUA script.(Citation: Cisco ArcaneDoor 2024)", "external_references": [{"description": "Cisco Talos. (2024, April 24). ArcaneDoor - New espionage-focused campaign found targeting perimeter network devices. Retrieved January 6, 2025.", "source_name": "Cisco ArcaneDoor 2024", "url": "https://blog.talosintelligence.com/arcanedoor-new-espionage-focused-campaign-found-targeting-perimeter-network-devices/"}], "id": "relationship--db5747cb-17f3-4e12-adda-49fd56650bc4", "modified": "2026-04-29T14:23:06.225Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5f8c69a5-7acd-4a36-a929-de558d9c8223", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17110', 0, 73, '09-mitre-attack', 'retrieved', 'D4FC1556D654519C2533941DC9B89E55E7BCA4E983F7EA6AEE27C6C516EE06F2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
