VALUES ('doc-09-mitre-attack-p0-17111', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-06T19:19:15.725Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Line Runner](https://attack.mitre.org/software/S1188) intercepts HTTP requests to the victim Cisco ASA, looking for a request with a 32-character, victim dependent parameter. If that parameter matches a value in the malware, a contained payload is then written to a Lua script and executed.(Citation: Cisco ArcaneDoor 2024)", "external_references": [{"description": "Cisco Talos. (2024, April 24). ArcaneDoor - New espionage-focused campaign found targeting perimeter network devices. Retrieved January 6, 2025.", "source_name": "Cisco ArcaneDoor 2024", "url": "https://blog.talosintelligence.com/arcanedoor-new-espionage-focused-campaign-found-targeting-perimeter-network-devices/"}], "id": "relationship--ea7bd047-2997-425a-81ea-bac54af153c7", "modified": "2026-04-29T14:23:06.244Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5f8c69a5-7acd-4a36-a929-de558d9c8223", "spec_version": "2.1", "target_ref": "attack-pattern--035bb001-ab69-4a0b-9f6c-2de8b09e1b9d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17111', 0, 100, '09-mitre-attack', 'retrieved', '63462F8020379A950050E606311658CEDB8B3AF2058F3CD817BC2C3BA0DE1C57', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
