VALUES ('doc-09-mitre-attack-p0-17124', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pteranodon](https://attack.mitre.org/software/S0147) can delete files that may interfere with it executing. It also can delete temporary files and itself after the initial script executes.(Citation: Palo Alto Gamaredon Feb 2017)", "external_references": [{"description": "Kasza, A. and Reichel, D. (2017, February 27). The Gamaredon Group Toolset Evolution. Retrieved March 1, 2017.", "source_name": "Palo Alto Gamaredon Feb 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/02/unit-42-title-gamaredon-group-toolset-evolution/"}], "id": "relationship--c8bceb4a-0cf2-43c9-9729-20ed706c4c72", "modified": "2026-04-29T14:23:06.200Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5f9f7648-04ba-4a9f-bb4c-2a13e74572bd", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17124', 0, 84, '09-mitre-attack', 'retrieved', '02DB127AF6620D44231C0AF5015B7046CCD51AAE84D3DB30EA3E0C416132DA47', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
