VALUES ('doc-09-mitre-attack-p0-17125', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pteranodon](https://attack.mitre.org/software/S0147) creates various subdirectories under %Temp%\\reports\\% and copies files to those subdirectories. It also creates a folder at C:\\Users\\ \\AppData\\Roaming\\Microsoft\\store to store screenshot JPEG files.(Citation: Palo Alto Gamaredon Feb 2017)", "external_references": [{"description": "Kasza, A. and Reichel, D. (2017, February 27). The Gamaredon Group Toolset Evolution. Retrieved March 1, 2017.", "source_name": "Palo Alto Gamaredon Feb 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/02/unit-42-title-gamaredon-group-toolset-evolution/"}], "id": "relationship--c93bb2b9-bd22-4e14-b884-2141168387b2", "modified": "2026-04-29T14:23:06.200Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5f9f7648-04ba-4a9f-bb4c-2a13e74572bd", "spec_version": "2.1", "target_ref": "attack-pattern--1c34f7aa-9341-4a48-bfab-af22e51aca6c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17125', 0, 86, '09-mitre-attack', 'retrieved', 'E687C0245B8C5F294F59D0A20B401B5292032775AA8C72E4C90BA39A3B279DBC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
