VALUES ('doc-09-mitre-attack-p0-17127', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-17T15:04:48.816Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pteranodon](https://attack.mitre.org/software/S0147) can use mshta.exe to execute an HTA file hosted on a remote server.(Citation: Symantec Shuckworm January 2022)", "external_references": [{"description": "Symantec. (2022, January 31). Shuckworm Continues Cyber-Espionage Attacks Against Ukraine. Retrieved February 17, 2022.", "source_name": "Symantec Shuckworm January 2022", "url": "https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/shuckworm-gamaredon-espionage-ukraine"}], "id": "relationship--d4e67bb3-dcb2-4427-a48e-d8b4bcc35afa", "modified": "2026-04-29T14:23:06.216Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5f9f7648-04ba-4a9f-bb4c-2a13e74572bd", "spec_version": "2.1", "target_ref": "attack-pattern--840a987a-99bd-4a80-a5c9-0cb2baa6cade", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17127', 0, 70, '09-mitre-attack', 'retrieved', 'BBAF63BD8A9F9E7B0DD35B82BF81FFFCA7FBE196BB70DAF23AA7F525CCA2A2B4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
