VALUES ('doc-09-mitre-attack-p0-17129', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-16T16:45:43.255Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkTortilla](https://attack.mitre.org/software/S1066) can download additional packages for keylogging, cryptocurrency mining, and other capabilities; it can also retrieve malicious payloads such as [Agent Tesla](https://attack.mitre.org/software/S0331), AsyncRat, [NanoCore](https://attack.mitre.org/software/S0336), RedLine, [Cobalt Strike](https://attack.mitre.org/software/S0154), and Metasploit.(Citation: Secureworks DarkTortilla Aug 2022)", "external_references": [{"description": "Secureworks Counter Threat Unit Research Team. (2022, August 17). DarkTortilla Malware Analysis. Retrieved November 3, 2022.", "source_name": "Secureworks DarkTortilla Aug 2022", "url": "https://www.secureworks.com/research/darktortilla-malware-analysis"}], "id": "relationship--02c8a28f-c188-47a9-ab93-d9abb862abab", "modified": "2026-04-29T14:23:05.907Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5faaf81a-aa5b-4a4b-bae5-522439e068f8", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17129', 0, 87, '09-mitre-attack', 'retrieved', 'E3707EBA07F01B2CA039526072392E8D13F82475139C57916D0839718D0EF474', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
