VALUES ('doc-09-mitre-attack-p0-17130', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-16T16:39:26.645Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkTortilla](https://attack.mitre.org/software/S1066) can decrypt its payload and associated configuration elements using the Rijndael cipher.(Citation: Secureworks DarkTortilla Aug 2022)", "external_references": [{"description": "Secureworks Counter Threat Unit Research Team. (2022, August 17). DarkTortilla Malware Analysis. Retrieved November 3, 2022.", "source_name": "Secureworks DarkTortilla Aug 2022", "url": "https://www.secureworks.com/research/darktortilla-malware-analysis"}], "id": "relationship--0977c267-10f9-4e4d-a947-464359c7a4ba", "modified": "2026-04-29T14:23:05.916Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5faaf81a-aa5b-4a4b-bae5-522439e068f8", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17130', 0, 71, '09-mitre-attack', 'retrieved', '33FF97A178213702B24EF7D7FDF1276B413F5EB7DE3BC8CAA68732042D8BABE6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
