VALUES ('doc-09-mitre-attack-p0-17131', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-16T16:51:36.388Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkTortilla](https://attack.mitre.org/software/S1066) has been obfuscated with the DeepSea .NET and ConfuserEx code obfuscators.(Citation: Secureworks DarkTortilla Aug 2022)", "external_references": [{"description": "Secureworks Counter Threat Unit Research Team. (2022, August 17). DarkTortilla Malware Analysis. Retrieved November 3, 2022.", "source_name": "Secureworks DarkTortilla Aug 2022", "url": "https://www.secureworks.com/research/darktortilla-malware-analysis"}], "id": "relationship--0b58e2e5-9be5-4132-a65f-19db8acd7033", "modified": "2026-04-29T14:23:05.919Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5faaf81a-aa5b-4a4b-bae5-522439e068f8", "spec_version": "2.1", "target_ref": "attack-pattern--b3d682b6-98f2-4fb0-aa3b-b4df007ca70a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17131', 0, 70, '09-mitre-attack', 'retrieved', '6D1B702B498DC0C830D7D65AFF5C7F548C047010E55F91A8D46BBAEC9D8ACF2A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
