VALUES ('doc-09-mitre-attack-p0-17135', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-04-13T19:55:13.908Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": " [DarkTortilla](https://attack.mitre.org/software/S1066) has established persistence via the `Software\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon` registry key.(Citation: Secureworks DarkTortilla Aug 2022)", "external_references": [{"description": "Secureworks Counter Threat Unit Research Team. (2022, August 17). DarkTortilla Malware Analysis. Retrieved November 3, 2022.", "source_name": "Secureworks DarkTortilla Aug 2022", "url": "https://www.secureworks.com/research/darktortilla-malware-analysis"}], "id": "relationship--2d14ce48-92d3-446d-84f3-a0df761e08fb", "modified": "2026-04-29T14:23:05.966Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5faaf81a-aa5b-4a4b-bae5-522439e068f8", "spec_version": "2.1", "target_ref": "attack-pattern--6836813e-8ec8-4375-b459-abb388cb1a35", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17135', 0, 69, '09-mitre-attack', 'retrieved', '69CCA6C14ADA7F3491A6B1E2625177372086C1554ACC008200126BC1A8026B6C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
