VALUES ('doc-09-mitre-attack-p0-17154', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-02-16T18:50:07.225Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkTortilla](https://attack.mitre.org/software/S1066) can detect debuggers by using functions such as `DebuggerIsAttached` and `DebuggerIsLogging`. [DarkTortilla](https://attack.mitre.org/software/S1066) can also detect profilers by verifying the `COR_ENABLE_PROFILING` environment variable is present and active.(Citation: Secureworks DarkTortilla Aug 2022)", "external_references": [{"description": "Secureworks Counter Threat Unit Research Team. (2022, August 17). DarkTortilla Malware Analysis. Retrieved November 3, 2022.", "source_name": "Secureworks DarkTortilla Aug 2022", "url": "https://www.secureworks.com/research/darktortilla-malware-analysis"}], "id": "relationship--c6cc5a76-522d-4b48-ae5b-4867fa87f2c6", "modified": "2026-04-29T14:23:06.197Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5faaf81a-aa5b-4a4b-bae5-522439e068f8", "spec_version": "2.1", "target_ref": "attack-pattern--e4dc8c01-417f-458d-9ee0-bb0617c1b391", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17154', 0, 85, '09-mitre-attack', 'retrieved', 'EC2ACA51D67CFAE79CA227C0FC820EEF730DC160FE3B0B4B7E76180DF820ED46', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
