VALUES ('doc-09-mitre-attack-p0-17157', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T18:24:59.121Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BeaverTail](https://attack.mitre.org/software/S1246) has used HTTP GET request to download malicious payloads to include [InvisibleFerret](https://attack.mitre.org/software/S1245) and HTTP POST to exfiltrate data to C2 infrastructure.(Citation: Socket BeaverTail XORIndex HexEval Contagious Interview July 2025)(Citation: PaloAlto ContagiousInterview BeaverTail InvisibleFerret November 2023)", "external_references": [{"description": "Kirill Boychenko. (2025, July 14). Contagious Interview Campaign Escalates With 67 Malicious npm Packages and New Malware Loader. Retrieved October 19, 2025.", "source_name": "Socket BeaverTail XORIndex HexEval Contagious Interview July 2025", "url": "https://socket.dev/blog/contagious-interview-campaign-escalates-67-malicious-npm-packages"}, {"description": "Unit 42. (2023, November 21). Hacking Employers and Seeking Employment: Two Job-Related Campaigns Bear Hallmarks of North Korean Threat Actors. Retrieved October 17, 2025.", "source_name": "PaloAlto ContagiousInterview BeaverTail InvisibleFerret November 2023", "url": "https://unit42.paloaltonetworks.com/two-campaigns-by-north-korea-bad-actors-target-job-hunters/"}], "id": "relationship--040ab48a-edc1-4ab1-97ee-7cffb9b226d7", "modified": "2026-04-29T14:23:05.909Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6055aee2-d1c6-4877-94e9-a3bde9936470", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17157', 0, 134, '09-mitre-attack', 