VALUES ('doc-09-mitre-attack-p0-17158', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T18:10:07.741Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BeaverTail](https://attack.mitre.org/software/S1246) has executed malicious JavaScript code.(Citation: Esentire ContagiousInterview BeaverTail InvisibleFerret November 2024)(Citation: Recorded Future Contagious Inteview BeaverTail InvisibleFerret OtterCookie February 2025)(Citation: ESET Contagious Interview BeaverTail InvisibleFerret February 2025)(Citation: Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024)(Citation: PaloAlto ContagiousInterview BeaverTail InvisibleFerret November 2023) [BeaverTail](https://attack.mitre.org/software/S1246) has also been compiled with the Qt framework to execute in both Windows and macOS.(Citation: PaloAlto Unit42 ContagiousInterview BeaverTail InvisibileFerret October 2024)", "external_references": [{"description": "eSentire Threat Response Unit (TRU). (2024, November 14). Bored BeaverTail & InvisibleFerret Yacht Club – A Lazarus Lure Pt.2. Retrieved October 17, 2025.", "source_name": "Esentire ContagiousInterview BeaverTail InvisibleFerret November 2024", "url": "https://www.esentire.com/blog/bored-beavertail-invisibleferret-yacht-club-a-lazarus-lure-pt-2"}, {"description": "Insikt Group. (2025, February 13). Inside the Scam: North Korea’s IT Worker Threat. Retrieved October 17, 2025.", "source_name": "Recorded Future Contagious Inteview BeaverTail InvisibleFerret OtterCookie February 2025", "url": "https://www.recordedfuture.com/research/inside-the-scam-north-koreas-it-worker-threat"}, {"description": "Matej Havranek. (2025, February 20). DeceptiveDevelopment targets freelance developers. Retrieved October 17, 2025.", "source_name": "ESET Contagious Interview BeaverTail InvisibleFerret February 2025", "url": "https://www.welivesecurity.com/en/eset-research/deceptivedevelopment-targets-freelance-developers/"}, {"description": "Seongsu Park. (2024, November 4). From Pyongyang to Your Payroll: The Rise of North Korean Remote Workers in the West. Retrieved October 17, 2025.", "source_name": "Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024", "url": "https://www.zscaler.com/blogs/security-research/pyongyang-your-payroll-rise-north-korean-remote-workers-west"}, {"description": "Unit 42. (2023, November 21). Hacking Employers and Seeking Employment: Two Job-Related Campaigns Bear Hallmarks of North Korean Threat Actors. Retrieved October 17, 2025.", "source_name": "PaloAlto ContagiousInterview BeaverTail InvisibleFerret November 2023", "url": "https://unit42.paloaltonetworks.com/two-campaigns-by-north-korea-bad-actors-target-job-hunters/"}, {"description": "Unit42. (2024, October 9). Contagious Interview: DPRK Threat Actors Lure Tech Industry Job Seekers to Install New Variants of BeaverTail and InvisibleFerret Malware. Retrieved October 17, 2025.", "source_name": "PaloAlto Unit42 ContagiousInterview BeaverTail InvisibileFerret October 2024", "url": "https://unit42.paloaltonetworks.com/north-korean-threat-actors-lure-tech-job-seekers-as-fake-recruiters/"}], "id": "relationship--0bdac0c4-3faa-429c-9945-a5e3763bee23", "modified": "2026-04-29T14:23:05.919Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6055aee2-d1c6-4877-94e9-a3bde9936470", "spec_version": "2.1", "target_ref": "attack-pattern--0f4a0c76-ab2d-4cb0-85d3-3f0efb8cba0d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17158', 0, 286, '09-mitre-attack', 'retrieved', '13C133DA93B7EC60825DBE8F0AB2945D17DCD8A54D09CE2B75F404DA5BACB7F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_t