VALUES ('doc-09-mitre-attack-p0-17171', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T18:01:16.852Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BeaverTail](https://attack.mitre.org/software/S1246) has collected keys stored for Solana stored in `.config/solana/id.json` and other login details associated with macOS within `/Library/Keychains/login.keychain` or for Linux within `/.local/share/keyrings`.(Citation: ESET Contagious Interview BeaverTail InvisibleFerret February 2025)", "external_references": [{"description": "Matej Havranek. (2025, February 20). DeceptiveDevelopment targets freelance developers. Retrieved October 17, 2025.", "source_name": "ESET Contagious Interview BeaverTail InvisibleFerret February 2025", "url": "https://www.welivesecurity.com/en/eset-research/deceptivedevelopment-targets-freelance-developers/"}], "id": "relationship--941fe970-2c7c-4c61-9125-b59b3ec9eb90", "modified": "2026-04-29T14:23:06.127Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6055aee2-d1c6-4877-94e9-a3bde9936470", "spec_version": "2.1", "target_ref": "attack-pattern--3fc9b85a-2862-4363-a64d-d692e3ffbee0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17171', 0, 85, '09-mitre-attack', 'retrieved', '4FEBFA1601A5DAAD2A3A0A37A3A1B4024C8D48A8D8DEFA292C3C647E10C4DB62', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
