VALUES ('doc-09-mitre-attack-p0-17173', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T17:54:02.413Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BeaverTail](https://attack.mitre.org/software/S1246) has added junk data or a dummy character prepended to a string to hamper decoding attempts.(Citation: ESET Contagious Interview BeaverTail InvisibleFerret February 2025)", "external_references": [{"description": "Matej Havranek. (2025, February 20). DeceptiveDevelopment targets freelance developers. Retrieved October 17, 2025.", "source_name": "ESET Contagious Interview BeaverTail InvisibleFerret February 2025", "url": "https://www.welivesecurity.com/en/eset-research/deceptivedevelopment-targets-freelance-developers/"}], "id": "relationship--a8b92dca-8843-4d3c-9bff-88c922201b09", "modified": "2026-04-29T14:23:06.155Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6055aee2-d1c6-4877-94e9-a3bde9936470", "spec_version": "2.1", "target_ref": "attack-pattern--f7c0689c-4dbd-489b-81be-7cb7c7079ade", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17173', 0, 78, '09-mitre-attack', 'retrieved', 'C3DD72C141EFD67C6F89022EB04F341CA8949B08BBD8FB39A8966CC3E561FF9B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
