VALUES ('doc-09-mitre-attack-p0-17180', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-22T20:09:04.380Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROKRAT](https://attack.mitre.org/software/S0240) can modify the `HKEY_CURRENT_USER\\Software\\Microsoft\\Office\\` registry key so it can bypass the VB object model (VBOM) on a compromised host.(Citation: Malwarebytes RokRAT VBA January 2021)", "external_references": [{"description": "Jazi, Hossein. (2021, January 6). Retrohunting APT37: North Korean APT used VBA self decode technique to inject RokRat. Retrieved March 22, 2022.", "source_name": "Malwarebytes RokRAT VBA January 2021", "url": "https://blog.malwarebytes.com/threat-analysis/2021/01/retrohunting-apt37-north-korean-apt-used-vba-self-decode-technique-to-inject-rokrat/"}], "id": "relationship--0ae212be-c07b-4f62-8c5e-9dfc0472254e", "modified": "2026-04-29T14:23:05.918Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--60a9c2f0-b7a5-4e8e-959c-e1a3ff314a5f", "spec_version": "2.1", "target_ref": "attack-pattern--57340c81-c025-4189-8fa0-fc7ede51bae4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17180', 0, 86, '09-mitre-attack', 'retrieved', '972621E368F712D8C97079726A109008503E4A57BC2F04F1D588BB04A6F3CB90', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
