VALUES ('doc-09-mitre-attack-p0-17203', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-22T20:09:04.260Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROKRAT](https://attack.mitre.org/software/S0240) can use `VirtualAlloc`, `WriteProcessMemory`, and then `CreateRemoteThread` to execute shellcode within the address space of `Notepad.exe`.(Citation: Malwarebytes RokRAT VBA January 2021)", "external_references": [{"description": "Jazi, Hossein. (2021, January 6). Retrohunting APT37: North Korean APT used VBA self decode technique to inject RokRat. Retrieved March 22, 2022.", "source_name": "Malwarebytes RokRAT VBA January 2021", "url": "https://blog.malwarebytes.com/threat-analysis/2021/01/retrohunting-apt37-north-korean-apt-used-vba-self-decode-technique-to-inject-rokrat/"}], "id": "relationship--cc470da4-82b7-4efb-aa09-f3e7402291df", "modified": "2026-04-29T14:23:06.204Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--60a9c2f0-b7a5-4e8e-959c-e1a3ff314a5f", "spec_version": "2.1", "target_ref": "attack-pattern--43e7dc91-05b2-474c-b9ac-2ed4fe101f4d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17203', 0, 83, '09-mitre-attack', 'retrieved', '8B613D0466EEA36AC264CD53372CB5547FA3042280AAA5899837629571F196C7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
