VALUES ('doc-09-mitre-attack-p0-17255', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-17T00:46:38.670Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Exbyte](https://attack.mitre.org/software/S1179) checks for the presence of a configuration file before completing execution.(Citation: Microsoft BlackByte 2023)", "external_references": [{"description": "Microsoft Incident Response. (2023, July 6). The five-day job: A BlackByte ransomware intrusion case study. Retrieved December 16, 2024.", "source_name": "Microsoft BlackByte 2023", "url": "https://www.microsoft.com/en-us/security/blog/2023/07/06/the-five-day-job-a-blackbyte-ransomware-intrusion-case-study/"}], "id": "relationship--0747ca0c-ff34-4364-bb17-765054d06533", "modified": "2026-04-29T14:23:05.913Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6207dd22-bf18-4c96-aada-c573a9bbf5ec", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17255', 0, 71, '09-mitre-attack', 'retrieved', '7B7606F06BA76F01A068830B87EFC7C97FE3AACD9EB7189A0474F523C4F64CA8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
