VALUES ('doc-09-mitre-attack-p0-17257', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-17T00:47:35.675Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Exbyte](https://attack.mitre.org/software/S1179) decodes and decrypts data stored in the configuration file with a key provided on the command line during execution.(Citation: Microsoft BlackByte 2023)", "external_references": [{"description": "Microsoft Incident Response. (2023, July 6). The five-day job: A BlackByte ransomware intrusion case study. Retrieved December 16, 2024.", "source_name": "Microsoft BlackByte 2023", "url": "https://www.microsoft.com/en-us/security/blog/2023/07/06/the-five-day-job-a-blackbyte-ransomware-intrusion-case-study/"}], "id": "relationship--59b93237-62e9-42bf-a3a4-8dc2148464f2", "modified": "2026-04-29T14:23:06.047Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6207dd22-bf18-4c96-aada-c573a9bbf5ec", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17257', 0, 79, '09-mitre-attack', 'retrieved', 'D5E015197D5944A038AF3670EBC0359321388A66DEC733E6DFC6AAA4F48FFE79', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
