VALUES ('doc-09-mitre-attack-p0-17337', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-27T19:19:22.407Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LunarLoader](https://attack.mitre.org/software/S1143) can verify the targeted host''s DNS name which is then used in the creation of a decyrption key.(Citation: ESET Turla Lunar toolset May 2024)", "external_references": [{"description": "Jurčacko, F. (2024, May 15). To the Moon and back(doors): Lunar landing in diplomatic missions. Retrieved June 26, 2024.", "source_name": "ESET Turla Lunar toolset May 2024", "url": "https://www.welivesecurity.com/en/eset-research/moon-backdoors-lunar-landing-diplomatic-missions/"}], "id": "relationship--2b31cfdc-efab-421a-bc37-ea9eaa156fc8", "modified": "2026-04-29T14:23:05.963Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6490afef-d88e-4e2b-b9d9-a472508ca59d", "spec_version": "2.1", "target_ref": "attack-pattern--707399d6-ab3e-4963-9315-d9d3818cd6a0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17337', 0, 84, '09-mitre-attack', 'retrieved', 'A9B53472232AF28158DF52F9BE8C3E2A669A10EFEF424BBF980649B45A2BBD3F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
