VALUES ('doc-09-mitre-attack-p0-17338', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-27T19:30:41.640Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LunarLoader](https://attack.mitre.org/software/S1143) can use the DNS domain name of a compromised host to create a decryption key to ensure a malicious payload can only execute against the intended targets.(Citation: ESET Turla Lunar toolset May 2024)", "external_references": [{"description": "Jurčacko, F. (2024, May 15). To the Moon and back(doors): Lunar landing in diplomatic missions. Retrieved June 26, 2024.", "source_name": "ESET Turla Lunar toolset May 2024", "url": "https://www.welivesecurity.com/en/eset-research/moon-backdoors-lunar-landing-diplomatic-missions/"}], "id": "relationship--79a92839-53b3-4ff2-90f4-8f9630b2da93", "modified": "2026-04-29T14:23:06.092Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6490afef-d88e-4e2b-b9d9-a472508ca59d", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17338', 0, 93, '09-mitre-attack', 'retrieved', 'F752B66DF94098CD341B440CC5B83CA82F4A2DD5D7AC24716F20DEDC6FBC1420', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
