VALUES ('doc-09-mitre-attack-p0-17346', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BBSRAT](https://attack.mitre.org/software/S0127) can start, stop, or delete services.(Citation: Palo Alto Networks BBSRAT)", "external_references": [{"description": "Lee, B. Grunzweig, J. (2015, December 22). BBSRAT Attacks Targeting Russian Organizations Linked to Roaming Tiger. Retrieved August 19, 2016.", "source_name": "Palo Alto Networks BBSRAT", "url": "http://researchcenter.paloaltonetworks.com/2015/12/bbsrat-attacks-targeting-russian-organizations-linked-to-roaming-tiger/"}], "id": "relationship--59b39f06-a71c-42f7-92f2-244a183113d6", "modified": "2026-04-29T14:23:06.047Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--64d76fa5-cf8f-469c-b78c-1a4f7c5bad80", "spec_version": "2.1", "target_ref": "attack-pattern--f1951e8a-500e-4a26-8803-76d95c4554b4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17346', 0, 69, '09-mitre-attack', 'retrieved', 'A4DD318A6864C04EA635CD4D3103DF66C48E0559376B27B1EAAD283FF80B0B12', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
