VALUES ('doc-09-mitre-attack-p0-17356', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-11T20:24:23.841Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PlugX](https://attack.mitre.org/software/S0013) has made calls to Windows API `CheckRemoteDebuggerPresent` and exits if it detects a debugger.(Citation: Sophos Mustang Panda PLUGX)", "external_references": [{"description": "Secureworks Counter Threat Unit Research Team. (2022, September 8). BRONZE PRESIDENT Targets Government Officials. Retrieved September 9, 2025.", "source_name": "Sophos Mustang Panda PLUGX", "url": "https://www.secureworks.com/blog/bronze-president-targets-government-officials"}], "id": "relationship--0644d7f4-edb2-4fbf-81bb-498d1962ad4e", "modified": "2026-04-29T14:23:05.912Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--64fa0de0-6240-41f4-8638-f4ca7ed528fd", "spec_version": "2.1", "target_ref": "attack-pattern--e4dc8c01-417f-458d-9ee0-bb0617c1b391", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17356', 0, 75, '09-mitre-attack', 'retrieved', 'FA1D7C8D670EE8D542776C431F765B9F2CB3527539A515B6D5B9BD358970479D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
