VALUES ('doc-09-mitre-attack-p0-17377', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-27T21:54:12.731Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A version of [PlugX](https://attack.mitre.org/software/S0013) loads as shellcode within a .NET Framework project using msbuild.exe, presumably to bypass application control techniques.(Citation: Palo Alto PlugX June 2017)", "external_references": [{"description": "Lancaster, T. and Idrizovic, E.. (2017, June 27). Paranoid PlugX. Retrieved July 13, 2017.", "source_name": "Palo Alto PlugX June 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/06/unit42-paranoid-plugx/"}], "id": "relationship--652af94a-7ff3-4d47-89e5-154c7bc34258", "modified": "2026-04-29T14:23:06.063Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--64fa0de0-6240-41f4-8638-f4ca7ed528fd", "spec_version": "2.1", "target_ref": "attack-pattern--c92e3d68-2349-49e4-a341-7edca2deff96", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17377', 0, 78, '09-mitre-attack', 'retrieved', 'D24ADBFCC4CE9FA6E201B75FA5E3165FB012224B3D770B4EF86C644B69B07A32', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
