VALUES ('doc-09-mitre-attack-p0-17382', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-04-04T17:20:49.848Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PlugX](https://attack.mitre.org/software/S0013) has modified local firewall rules on victim machines to enable a random, high-number listening port for subsequent access and C2 activity.(Citation: Sygnia VelvetAnt 2024A)", "external_references": [{"description": "Sygnia Team. (2024, June 3). China-Nexus Threat Group ‘Velvet Ant’ Abuses F5 Load Balancers for Persistence. Retrieved March 14, 2025.", "source_name": "Sygnia VelvetAnt 2024A", "url": "https://www.sygnia.co/blog/china-nexus-threat-group-velvet-ant/"}], "id": "relationship--80e9ec9c-ecb4-48c3-944c-e318fec4a656", "modified": "2026-04-29T14:23:06.102Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--64fa0de0-6240-41f4-8638-f4ca7ed528fd", "spec_version": "2.1", "target_ref": "attack-pattern--eec096b8-c207-43df-b6c1-11523861e452", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17382', 0, 82, '09-mitre-attack', 'retrieved', 'E01C4F29FF6F85DD77C22D93724312DF7CD363923A6367237D077604887CD02A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
